/* ===================== BÀI 28 · Dữ liệu chồng lấn và biên ===================== */
/* Bài 28 · Dữ liệu chồng lấn và biên (AMTS-EMB-002-M07-L04, X86-028) — sinh bởi tools/author/mpu8086/l28.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P28=[{"label": "Ví dụ: dời trái chồng lấn, đi xuôi", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      'XABCDE', '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD                             ; đích (buf) trước nguồn (buf+1)\n        LEA     SI, buf+1\n        LEA     DI, buf\n        MOV     CX, 5\n        REP     MOVSB                   ; dời trái 1: an toàn khi đi xuôi\n        MOV     buf+5, '.'\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Xóa X ở đầu XABCDE: nguồn buf + 1, đích buf (đích trước nguồn) nên chép xuôi an toàn. REP MOVSB 5 byte: 9 + 17 × 5 = 94 chu kỳ. MOV buf+5, '.' (16 chu kỳ) xóa ô cuối. In ABCDE.. Đoán trước: trước REP MOVSB, CX bằng bao nhiêu? Đáp án 0005h."}, {"label": "Lỗi: dời phải bằng chép xuôi", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      'ABCDE.', '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     SI, buf                 ; nguồn\n        LEA     DI, buf+1               ; LỖI: đích sau nguồn, chồng lấn\n        MOV     CX, 5\n        REP     MOVSB                   ; byte vừa ghi bị đọc lại\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: dời phải bằng chép xuôi. Lần 1 ghi A vào buf + 1 trước khi B được đọc; lần 2 đọc lại chính chữ A đó. Kết quả AAAAAA (xem phần Bộ nhớ). Sửa: chép ngược như Ví dụ 3. Đoán trước: sau lệnh REP, byte buf + 5 là gì? Đáp án A."}, {"label": "Ví dụ: dời phải bằng STD, đi ngược", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      'ABCDE.', '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        STD                             ; đích sau nguồn: đi ngược\n        LEA     SI, buf+4               ; byte cuối của nguồn\n        LEA     DI, buf+5               ; byte cuối của đích\n        MOV     CX, 5\n        REP     MOVSB\n        CLD\n        MOV     buf, 'X'                ; chèn X vào đầu\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Dời phải đúng: STD, SI = buf + 4 (E, byte cuối nguồn), DI = buf + 5. Mỗi byte được đọc trước khi bị ghi. Sau REP, SI = FFFFh (0 − 1), DI = 0000h. CLD rồi ghi X vào buf: in XABCDE. Đoán trước: lần chép đầu tiên ghi vào ô nào? Đáp án buf + 5."}, {"label": "Ví dụ: thủ tục DOI tự chọn hướng", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      'ABCDEFGH', 13, 10, '$'\nbuf2    DB      'ABCDEFGH', '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        LEA     SI, buf                 ; ca 1: dời phải 2 (đích sau nguồn)\n        LEA     DI, buf+2\n        MOV     CX, 6\n        CALL    DOI\n        LEA     SI, buf2+2              ; ca 2: dời trái 2 (đích trước)\n        LEA     DI, buf2\n        MOV     CX, 6\n        CALL    DOI\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        LEA     DX, buf2\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; DOI: chép CX byte từ DS:SI sang ES:DI, đúng cả khi chồng lấn\n; ra: DF = 0. Đổi SI, DI, CX.\nDOI     PROC\n        CLD\n        CMP     DI, SI\n        JBE     XUOI                    ; đích không sau nguồn: đi xuôi\n        ADD     SI, CX                  ; đích sau nguồn: đi ngược từ cuối\n        DEC     SI\n        ADD     DI, CX\n        DEC     DI\n        STD\nXUOI:   REP     MOVSB\n        CLD\n        RET\nDOI     ENDP\n        END     MAIN\n", "input": "", "note": "Thủ tục DOI tự chọn hướng bằng CMP DI, SI. Ca 1 (đích sau nguồn, dời phải 2): đi ngược, ABCDEFGH thành ABABCDEF. Ca 2 (đích trước nguồn, dời trái 2): đi xuôi, ABCDEFGH thành CDEFGHGH. DOI luôn trả DF = 0. Đoán trước: ở ca 2, JBE XUOI có nhảy không? Đáp án có."}, {"label": "Bẫy: bắt đầu ở buf+N, mất dấu $", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      'ABCDE.', '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        STD\n        LEA     SI, buf+5               ; BẪY: buf+N thay vì buf+N-1\n        LEA     DI, buf+6\n        MOV     CX, 5\n        REP     MOVSB\n        CLD\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: bắt đầu ở buf + 5 và buf + 6 (sai một). Lần ghi đầu đè dấu $ ở buf + 6, phần chép lệch một ô (ABBCDE.). INT 21h hàm 09h không gặp $ nên in tràn; trình mô phỏng dừng sau 4000 ký tự và báo lỗi. Sửa: buf + 4 và buf + 5. Đoán trước: byte buf + 6 sau REP là gì? Đáp án '.' (2Eh)."}, {"label": "Bẫy: DI quay vòng ở biên đoạn 64 KB", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      'ABCD', '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        MOV     DI, 0FFFEH              ; 2 byte cuối của đoạn ES\n        MOV     AL, '#'\n        MOV     CX, 4\n        REP     STOSB                   ; DI: FFFE, FFFF, 0000, 0001\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: DI = FFFEh, REP STOSB 4 byte. DI đi FFFE, FFFF rồi quay về 0000, 0001 trong cùng đoạn ES (không sang đoạn kế), nên hai byte đầu của buf thành ##; in ##CD. Đoán trước: sau REP, DI bằng bao nhiêu? Đáp án 0002h."}, {"label": "Ví dụ: chèn vào mảng word bằng REP MOVSW", "code": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DW      10, 20, 30, 40, ?       ; 4 phần tử, còn 1 chỗ\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        STD                             ; dời 30, 40 sang phải 1 word\n        LEA     SI, mang+6              ; word cuối: phần tử 3 (40)\n        LEA     DI, mang+8\n        MOV     CX, 2\n        REP     MOVSW\n        CLD\n        MOV     mang+4, 25              ; chèn 25 vào chỗ trống\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Chèn 25 vào mảng word đã sắp 10, 20, 30, 40. STD, SI = mang + 6 (word cuối = 40), DI = mang + 8, CX = 2: REP MOVSW dời 40 rồi 30 sang phải một word (9 + 17 × 2 = 43 chu kỳ). Ghi 25 vào mang + 4: mảng thành 10, 20, 25, 30, 40. Đoán trước: sau REP, SI bằng bao nhiêu? Đáp án 0002h."}];
const sim28=makeX86Sim(document.getElementById("x86-l28"),{id:"s28",presets:P28,file:"BAI28.ASM"});
makeX86Ex(document.getElementById("ex-l28"),sim28,[{"t": "Xóa một ký tự: dời trái", "d": "Đọc 8 phím vào buf, rồi một chữ số k (1–8) (INT 21h hàm 08h). Xóa ký tự thứ k bằng cách dời các ký tự sau nó sang trái một ô (một lệnh REP MOVSB), ghi dấu chấm vào ô cuối rồi in buf bằng INT 21h hàm 09h. Ví dụ ABCDEFGH4 in ABCEFGH. (7 chữ rồi một dấu chấm). Code mẫu chép sai hướng: sửa lại. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      8 DUP(0), '$'\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, buf                 ; đọc 8 phím\n        MOV     CX, 8\nDOC:    MOV     AH, 08H\n        INT     21H\n        STOSB\n        LOOP    DOC\n        MOV     AH, 08H                 ; k = 1..8: vị trí cần xóa\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        MOV     BX, AX                  ; BX = k\n        MOV     CX, 8\n        SUB     CX, BX                  ; CX = số byte sau vị trí k\n        STD                             ; TODO: hướng này đúng chưa?\n        LEA     SI, buf+7\n        LEA     DI, buf+6\n        REP     MOVSB\n        CLD\n        MOV     buf+7, '.'              ; ô cuối trống\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDEFGH1", "out": "BCDEFGH."}, {"in": "ABCDEFGH8", "out": "ABCDEFG."}, {"in": "ABCDEFGH4", "out": "ABCEFGH."}, {"in": "123456785", "out": "1234678."}, {"in": "AAAABBBB4", "out": "AAABBBB."}, {"in": "xyzxyzxy2", "out": "xzxyzxy."}]}, {"t": "Chèn một ký tự: dời phải", "d": "Đọc 7 phím vào buf (8 ô, ô cuối trống), rồi ký tự c và chữ số k (1–8) (INT 21h hàm 08h). Chèn c vào vị trí k: dời các ký tự từ vị trí k sang phải một ô bằng một lệnh REP MOVSB, ghi c vào vị trí k, in buf. Ví dụ ABCDEFGX4 in ABCXDEFG. Code mẫu chép xuôi nên hỏng dữ liệu: sửa lại. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      8 DUP('.'), '$'         ; 7 ký tự + 1 chỗ trống\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        CLD\n        LEA     DI, buf                 ; đọc 7 phím\n        MOV     CX, 7\nDOC:    MOV     AH, 08H\n        INT     21H\n        STOSB\n        LOOP    DOC\n        MOV     AH, 08H                 ; ký tự cần chèn\n        INT     21H\n        MOV     DL, AL\n        MOV     AH, 08H                 ; k = 1..8\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        MOV     BX, AX                  ; BX = k\n        MOV     CX, 8\n        SUB     CX, BX                  ; CX = số byte phải dời\n        LEA     SI, buf[BX-1]           ; TODO: chép xuôi có đúng không?\n        LEA     DI, buf[BX]\n        REP     MOVSB\n        MOV     buf[BX-1], DL           ; ghi ký tự vào vị trí k\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDEFGX1", "out": "XABCDEFG"}, {"in": "ABCDEFGX8", "out": "ABCDEFGX"}, {"in": "ABCDEFGX4", "out": "ABCXDEFG"}, {"in": "1234567#2", "out": "1#234567"}, {"in": "AAAAAAAB7", "out": "AAAAAABA"}, {"in": "xyzxyzx.5", "out": "xyzx.yzx"}]}, {"t": "Dời 40 byte nhanh", "d": "buf có 40 ký tự và 10 ô trống (dấu chấm) phía sau. Đọc chữ số d (0–9) (INT 21h hàm 08h), dời cả 40 ký tự sang phải d ô (vùng chồng lấn), điền dấu chấm vào d ô đầu rồi in buf. Phần đọc, điền và in đã có. Code mẫu chép ngược từng byte bằng MOVSB + LOOP: đúng nhưng chậm. Viết lại phần chép để chạy không quá 850 chu kỳ ở test chậm nhất và mã không quá 58 byte. Kết thúc bằng INT 21h hàm 4Ch.", "start": "        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbuf     DB      'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd'\n        DB      10 DUP('.'), '$'        ; 10 ô trống sau 40 ký tự\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX\n        MOV     AH, 08H                 ; d = 0..9: dời phải d ô\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        MOV     BX, AX                  ; BX = d\n        STD                             ; đi ngược, từng byte, LOOP\n        LEA     SI, buf+39\n        LEA     DI, buf[BX+39]\n        MOV     CX, 40\nCHEP:   MOVSB\n        LOOP    CHEP\n        CLD\n        LEA     DI, buf                 ; d ô đầu thành dấu chấm\n        MOV     CX, BX\n        MOV     AL, '.'\n        REP     STOSB\n        LEA     DX, buf\n        MOV     AH, 09H\n        INT     21H\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "0", "out": "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd.........."}, {"in": "1", "out": ".ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd........."}, {"in": "2", "out": "..ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd........"}, {"in": "5", "out": ".....ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd....."}, {"in": "8", "out": "........ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd.."}, {"in": "9", "out": ".........ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789abcd."}], "perf": {"cycles": 850, "bytes": 58}}]);

makeQuiz("quiz28","score28",[{"q": "Chép n = 6 byte từ s = 0100h sang d = 0102h (cùng đoạn). Hai vùng có chồng lấn không, và phải chép theo hướng nào?", "o": ["Có; đích sau nguồn nên chép xuôi (CLD) từ byte đầu", "Có; đích sau nguồn nên chép ngược (STD) từ byte cuối", "Không chồng lấn vì d khác s; hướng nào cũng đúng", "Có; phải chép qua một vùng đệm thứ ba vì 8086 không làm được"], "a": 1, "e": "0100h < 0102h + 6 và 0102h < 0100h + 6 nên chồng lấn; d > s nên chép xuôi sẽ ghi đè byte chưa đọc. Đi ngược từ SI = 0105h, DI = 0107h là đủ, không cần vùng đệm."}, {"q": "buf chứa ABCD. Sau đoạn code, buf là gì?<pre class=\"mp-asm\">        CLD\n        LEA     SI, buf\n        LEA     DI, buf+1\n        MOV     CX, 3\n        REP     MOVSB<\/pre>", "o": ["AAAA", "AABC", "ABCD", "ABBC"], "a": 0, "e": "Đích sau nguồn mà chép xuôi: lần 1 ghi A vào buf+1, lần 2 đọc lại A đó ghi vào buf+2, lần 3 tương tự: AAAA. Muốn AABC phải chép ngược (STD, SI = buf+2, DI = buf+3)."}, {"q": "Chép ngược n word từ s sang d bằng <code>STD<\/code> / <code>REP MOVSW<\/code>. SI, DI bắt đầu ở đâu?", "o": ["SI = s + n − 1, DI = d + n − 1", "SI = s + 2n, DI = d + 2n", "SI = s, DI = d, vì DF tự đưa SI, DI về cuối", "SI = s + 2n − 2, DI = d + 2n − 2"], "a": 3, "e": "Word cuối bắt đầu ở byte s + 2(n − 1). s + n − 1 là công thức cho byte; s + 2n đã ra ngoài vùng; DF chỉ quyết định chiều cộng trừ sau mỗi phần tử, không tự dời điểm đầu."}, {"q": "ES = 0712h, DI = FFFFh, DF = 0. Hai lệnh <code>STOSB<\/code> liên tiếp ghi vào đâu?", "o": ["0712:FFFF rồi 0713:0000", "0712:FFFF rồi 0712:0000 kèm ngắt báo tràn", "0712:FFFF rồi 0712:0000", "Lệnh thứ hai không ghi vì DI đã tới giới hạn"], "a": 2, "e": "DI là thanh ghi 16 bit: FFFFh + 1 = 0000h, ES không đổi, nên byte thứ hai ghi vào đầu cùng đoạn (Ví dụ 6). 8086 không có ngắt hay giới hạn nào cho trường hợp này."}, {"q": "Xóa phần tử thứ 3 khỏi chuỗi 8 byte bằng cách dời 5 byte sau nó sang trái một ô. Cách nào đúng?", "o": ["STD, SI = buf + 7, DI = buf + 6, CX = 5, REP MOVSB", "CLD, SI = buf + 3, DI = buf + 2, CX = 5, REP MOVSB", "CLD, SI = buf + 2, DI = buf + 3, CX = 5, REP MOVSB", "CLD, SI = buf + 3, DI = buf + 2, CX = 6, REP MOVSB"], "a": 1, "e": "Đích trước nguồn nên chép xuôi từ đầu. Chép ngược từ cuối nhân bản byte cuối (lỗi của code mẫu bài tập 1); đảo SI, DI là dời phải; CX = 6 đọc thêm một byte ngoài chuỗi."}]);

